class GridParser:
    def __init__(self):
        self.current_task = None
        self.grids = {}
        self.demos = []
        self.test_input = None

    def parse_line(self, line):
        try:
            obj = json.loads(line)
            if 'message' in obj or 'userMessage' in obj or 'assistantMessage' in obj:
                content = obj.get('message', obj).get('content', {})
                if not isinstance(content, str):
                    content = [c for c in content if isinstance(c, dict)]
                    content = [c.get('text', '') for c in content if 'text' in c and c['text']]
                    if content:
                        content = content[0]
                else:
                    content = content

                # Check for task info
                if 'Task id' in content:
                    self.current_task = re.search(r'Task id:\s*(\S+)', content).group(1)
                if 'Test input' in content:
                    m = re.search(r'Test input \( (\d+)x(\d+) \):\s*\n([\d\s\n]+)', content)
                    if m:
                        self.test_input = self.clean_grid(m.group(3))
                        print(f"Found test input: {self.test_input.shape}")
                        print(self.test_input)
                        print("-" * 40)
                if 'Demo pair' in content:
                    if 'output' in content.lower():
                        m = re.search(r'Demo pair \d+ output \( (\d+)x(\d+) \):\s*\n([\d\s\n]+)', content)
