                            self.demos.append(('demo_output', self.clean_grid(m.group(2)), None))
                            print(f"Found demo output: {self.demos[-1][1].shape}")
                            print(self.demos[-1][1])
                            print("=" * 40)
                    else:
                        m = re.search(r'Demo pair (\d+) (input|output) \( (\d+)x(\d+) \):\s*\n([\d\s\n]+)', content)
                        if m:
                            self.demos.append((m.group(2), self.clean_grid(m.group(4)), None))
                            print(f"Found demo {m.group(2)}: {self.demos[-1][1].shape}")
                            print(self.demos[-1][1])
                            print("-" * 40)
        except Exception as e:
            pass

    def clean_grid(self, text):
        lines = text.split('\n')
        rows = []
        for line in lines:
            line = line.strip()
            if line and all(c.isdigit() or c in ' .-\t' for c in line):
                rows.append([int(x) for x in line.split()])
        return rows

